SELECT e.doc_id, count() AS impressions, countDistinct(e.reader_key) AS reach, sum(toUInt64(1)) AS f_oracle_impressions, LENGTH(groupUniqArray(e.reader_key)) AS f_oracle_reach FROM content_events AS e WHERE e.service = 'posts' AND e.event_type = 'delivery' AND e.doc_id IN ('0204') AND e.doc_id IN (SELECT doc_id FROM doc_groups WHERE group_id IN ('g1') AND deleted = 0) GROUP BY e.doc_id FORMAT JSON